function quicksort(arr) {
  if (arr.length <= 1) return arr;
  const pivot = arr[0];
  const less = arr.slice(1).filter(x => x < pivot);
  const more = arr.slice(1).filter(x => x >= pivot);
  return [...quicksort(less), pivot, ...quicksort(more)];
}

