class Buffer {
public:
  int* data;
  int size;
  Buffer(int n) : size(n) { data = new int[n]; }
  Buffer(const Buffer& o) : size(o.size) {
    data = new int[size];
    for (int i = 0; i < size; i++) data[i] = o.data[i];
  }
  ~Buffer() { delete[] data; }
};

Buffer& operator=(const Buffer& o) {
  if (this != &o) {
    delete[] data;
    size = o.size;
    data = new int[size];
    for (int i = 0; i < size; i++) data[i] = o.data[i];
  }
  return *this;
}

