template<typename K, typename V>
class HashMap {
  struct Entry { K key; V value; };
  std::vector<std::vector<Entry>> buckets;
public:
  HashMap() : buckets(16) {}
  void put(K key, V value) {
    int h = std::hash<K>{}(key) % buckets.size();
    buckets[h].push_back({key, value});
  }
};

